code='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)+1
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)+1
            if len(cells) >= 5:
                boxes.append((r0,r1,c0,c1))

    best = None
    for i, A in enumerate(boxes):
        for B in boxes[i+1:]:
            ar0,ar1,ac0,ac1=A; br0,br1,bc0,bc1=B
            H=min(ar1-ar0,br1-br0); W=min(ac1-ac0,bc1-bc0)
            # Compare same-size subwindows inside each pair of separate motifs.
            for hh in range(2,H+1):
                for ww in range(3,W+1):
                    for ay in range(ar0,ar1-hh+1):
                        for ax in range(ac0,ac1-ww+1):
                            for by in range(br0,br1-hh+1):
                                for bx in range(bc0,bc1-ww+1):
                                    eq=union=0
                                    for dy in range(hh):
                                        for dx in range(ww):
                                            va=grid[ay+dy][ax+dx]; vb=grid[by+dy][bx+dx]
                                            if va or vb:
                                                union+=1
                                                if va==vb: eq+=1
                                    # Prefer the largest shared motif, not a tiny coincidental match.
                                    if union < 12 or eq < 8 or eq == union:
                                        continue
                                    key=(eq, union, hh*ww)
                                    if best is None or key > best[0]:
                                        diff=[[8 if grid[ay+dy][ax+dx] != grid[by+dy][bx+dx] else 0 for dx in range(ww)] for dy in range(hh)]
                                        best=(key,diff)
    if best is None:
        return [[0]]
    out=best[1]
    rs=[r for r,row in enumerate(out) if any(row)]
    cs=[c for c in range(len(out[0])) if any(out[r][c] for r in range(len(out)))]
    return [[out[r][c] for c in range(min(cs),max(cs)+1)] for r in range(min(rs),max(rs)+1)]
'''
